/* Reviews in one place (Reviews › Overview, Reviews, Requests, Analytics, Settings). `review_import_batches`: one row per CSV import (Reviews › Import), with the file's name, how many rows it had, how many came in, how many were skipped and why (`report`), and when it was taken back (`undone_at`); `reviews.import_batch_id` names the import a review came from, so a whole import can be taken back. Server only, as `review_requests` is (part 134): row level security on, nothing for anon or authenticated, and the new column is not readable by the public key (part 134 grants the public its columns one by one, and this one is not among them). The two review buckets take one short video a review: MP4, WebM or QuickTime, at most 50 MB a file (pictures keep the 8 MB the server checks them against). `store_settings.reviews` may be up to 16 KB, room for the request email's own words. Two indexes Reviews › Requests reads by (newest by due date, and an address and product for the one-ask rule). No rows change. Needs part 134; each statement skips itself with a notice where what it needs is not there. Until it runs, an import still works and its report shows on the page, but it is not kept and cannot be taken back; videos say they turn on after the store's database update; long email words say to run this part. Safe to run again. */
DO $do$ BEGIN IF to_regclass('public.reviews') IS NULL OR to_regclass('public.creators') IS NULL THEN RAISE NOTICE 'reviews dashboard: the reviews table is not there yet, run part 52 and part 134 first.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.review_import_batches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL REFERENCES public.creators(id) ON DELETE CASCADE, file_name text CHECK (file_name IS NULL OR char_length(file_name) <= 120), total integer NOT NULL DEFAULT 0 CHECK (total >= 0), imported integer NOT NULL DEFAULT 0 CHECK (imported >= 0), skipped integer NOT NULL DEFAULT 0 CHECK (skipped >= 0), report jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(report) = 'object' AND pg_column_size(report) < 65536), created_at timestamptz NOT NULL DEFAULT now(), undone_at timestamptz); CREATE INDEX IF NOT EXISTS review_import_batches_creator ON public.review_import_batches (creator_id, created_at DESC); ALTER TABLE public.review_import_batches ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.review_import_batches FROM PUBLIC, anon, authenticated; GRANT ALL ON public.review_import_batches TO service_role; ALTER TABLE public.reviews ADD COLUMN IF NOT EXISTS import_batch_id uuid REFERENCES public.review_import_batches(id) ON DELETE SET NULL; CREATE INDEX IF NOT EXISTS reviews_import_batch ON public.reviews (import_batch_id) WHERE import_batch_id IS NOT NULL; END $do$;
DO $do$ BEGIN IF to_regclass('public.review_requests') IS NULL THEN RAISE NOTICE 'reviews dashboard: review_requests is not there yet, run part 134 first.'; RETURN; END IF; CREATE INDEX IF NOT EXISTS review_requests_creator_due ON public.review_requests (creator_id, due_at DESC); CREATE INDEX IF NOT EXISTS review_requests_creator_email_product ON public.review_requests (creator_id, email, product_id); END $do$;
DO $do$ BEGIN IF to_regclass('public.store_settings') IS NULL OR NOT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'store_settings' AND column_name = 'reviews') THEN RAISE NOTICE 'reviews dashboard: store_settings.reviews is not there yet, run part 134 first.'; RETURN; END IF; ALTER TABLE public.store_settings DROP CONSTRAINT IF EXISTS store_settings_reviews_check; ALTER TABLE public.store_settings ADD CONSTRAINT store_settings_reviews_check CHECK (jsonb_typeof(reviews) = 'object' AND pg_column_size(reviews) < 16384); END $do$;
DO $do$ BEGIN IF to_regclass('storage.buckets') IS NULL THEN RAISE NOTICE 'reviews dashboard: no storage schema here, the buckets were left alone.'; RETURN; END IF; UPDATE storage.buckets SET file_size_limit = 52428800, allowed_mime_types = ARRAY['image/jpeg', 'image/png', 'image/webp', 'image/gif', 'image/avif', 'video/mp4', 'video/webm', 'video/quicktime'] WHERE id IN ('review-photos', 'review-uploads'); END $do$;
notify pgrst, 'reload schema';
